begin;
do $$ declare master_id uuid; engineer uuid; buyer uuid; cid uuid; pid uuid; pid2 uuid; cat public.input_catalog; bid uuid; oid uuid; own_order uuid; evaluation jsonb; payload jsonb; q1 uuid; q2 uuid; rid uuid; begin
 select id,company_id into master_id,cid from public.profiles where role='MASTER' and active limit 1;
 select id into engineer from public.profiles where role='ENGINEERING' and company_id=cid and active limit 1;
 select id into buyer from public.profiles where role='PURCHASING' and company_id=cid and active limit 1;
 select id into pid from public.projects where company_id=cid limit 1;
 if engineer is null or buyer is null or pid is null then raise exception 'Fixtures required'; end if;
 select * into cat from public.input_catalog where catalog_active and input_type='MATERIAL' limit 1;
 perform set_config('request.jwt.claim.sub',master_id::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',master_id,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 perform public.save_project_access(pid,engineer,true,'{"maxAmount":24,"maxDeviation":20,"category":"MATERIAL"}');
 perform public.save_project_access(pid,buyer,true,null);
 bid:=public.save_budget_version(pid,jsonb_build_object('title','ACCESS ROLLBACK','baseDate','2026-11-07','bdiConfig','{"ac":5.29,"sg":0.25,"r":1,"df":1.01,"l":8,"cp":3.65,"issBase":60,"issRate":5}'::jsonb,'items',jsonb_build_array(jsonb_build_object('inputId',cat.id,'code',cat.catalog_code,'unit',cat.unit,'source','shared','quantity',2,'unitPrice',10))));
 perform public.set_budget_baseline(pid,bid);
 payload:=jsonb_build_object('supplier','ACCESS TEST '||gen_random_uuid(),'items',jsonb_build_array(jsonb_build_object('code',cat.catalog_code,'source','shared','unit',cat.unit,'quantity',2,'unitPrice',12)));
 oid:=(public.procurement_action('ORDER',pid,payload)->>'id')::uuid;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',engineer::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',engineer,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 evaluation:=public.evaluate_order_approval(oid);
 if not (evaluation->>'allowed')::boolean then raise exception 'Boundary approval rejected: %',evaluation; end if;
 begin perform public.procurement_action('APPROVE',pid,jsonb_build_object('id',oid));raise exception 'ASSERT missing reason accepted';exception when others then if sqlerrm='ASSERT missing reason accepted' then raise;end if;end;
 begin perform public.save_project_access(pid,buyer,false,null);raise exception 'ASSERT non-master config';exception when others then if sqlerrm='ASSERT non-master config' then raise;end if;end;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',master_id::text,true);
 perform public.save_project_access(pid,engineer,true,'{"maxAmount":23,"maxDeviation":20}');
 perform set_config('request.jwt.claim.sub',engineer::text,true);
 if (public.evaluate_order_approval(oid)->>'allowed')::boolean then raise exception 'Amount limit ignored';end if;
 perform set_config('request.jwt.claim.sub',master_id::text,true);
 perform public.save_project_access(pid,engineer,true,'{"maxAmount":24,"maxDeviation":19}');
 perform set_config('request.jwt.claim.sub',engineer::text,true);
 if (public.evaluate_order_approval(oid)->>'allowed')::boolean then raise exception 'Deviation limit ignored';end if;
 perform set_config('request.jwt.claim.sub',master_id::text,true);
 perform public.save_project_access(pid,engineer,true,'{"maxAmount":24,"maxDeviation":20,"category":"EQUIPMENT"}');
 perform set_config('request.jwt.claim.sub',engineer::text,true);
 if (public.evaluate_order_approval(oid)->>'allowed')::boolean then raise exception 'Category limit ignored';end if;
 perform set_config('request.jwt.claim.sub',master_id::text,true);
 perform public.save_project_access(pid,engineer,false,null);
 perform set_config('request.jwt.claim.sub',engineer::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',engineer,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 if exists(select 1 from public.projects where id=pid) or exists(select 1 from public.budgets where project_id=pid) or exists(select 1 from public.budget_items where budget_id=bid) or exists(select 1 from public.purchase_order_items where order_id=oid) then raise exception 'RLS project leak'; end if;
 if public.can_access_operation_file('order',oid,pid,false) then raise exception 'File access leak';end if;
 begin perform public.executive_report_snapshot(pid);raise exception 'ASSERT report leak';exception when others then if sqlerrm='ASSERT report leak' then raise;end if;end;
 begin perform public.procurement_origins(pid);raise exception 'ASSERT origins leak';exception when others then if sqlerrm='ASSERT origins leak' then raise;end if;end;
 begin perform public.archive_document('budget',bid,'Unauthorized archive');raise exception 'ASSERT archive bypass';exception when others then if sqlerrm='ASSERT archive bypass' then raise;end if;end;
 begin perform public.procurement_action('APPROVE',pid,jsonb_build_object('id',oid,'reason','Bypass revoked project'));raise exception 'ASSERT approval bypass';exception when others then if sqlerrm='ASSERT approval bypass' then raise;end if;end;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',master_id::text,true);
 perform public.save_project_access(pid,engineer,true,'{"maxAmount":24,"maxDeviation":20}');
 perform set_config('request.jwt.claim.sub',engineer::text,true);
 execute 'set local role authenticated';
 perform public.procurement_action('APPROVE',pid,jsonb_build_object('id',oid,'reason','Dentro dos limites delegados'));
 execute 'reset role';
 if not exists(select 1 from public.purchase_orders where id=oid and approved_by=engineer and approval_snapshot->'rule'->>'max_amount'='24.00') then raise exception 'Decision snapshot absent';end if;
 if not exists(select 1 from public.operation_audit where entity_id=oid and action='APPROVE' and details->>'justification'='Dentro dos limites delegados') then raise exception 'Decision audit absent';end if;
 perform set_config('request.jwt.claim.sub',master_id::text,true);
 perform public.save_project_access(pid,buyer,true,'{"maxAmount":10000,"maxDeviation":100}');
 perform set_config('request.jwt.claim.sub',buyer::text,true);
 own_order:=(public.procurement_action('ORDER',pid,payload)->>'id')::uuid;
 if (public.evaluate_order_approval(own_order)->>'allowed')::boolean then raise exception 'Own approval permitted';end if;
 perform set_config('request.jwt.claim.sub',master_id::text,true);
 payload:=jsonb_build_object('roundTitle','ACCESS QUOTE','title','Proposta A','supplierName','ACCESS A '||gen_random_uuid(),'validUntil',(current_date+7)::text,'expectedAt',(current_date+3)::text,'items',jsonb_build_array(jsonb_build_object('inputId',cat.id,'source','shared','code',cat.catalog_code,'unit',cat.unit,'quantity',2,'unitPrice',12)));
 q1:=public.save_comparable_quote(pid,payload);
 select round_id into rid from public.quotations where id=q1;
 q2:=public.save_comparable_quote(pid,payload||jsonb_build_object('roundId',rid,'supplierName','ACCESS B '||gen_random_uuid()));
 perform set_config('request.jwt.claim.sub',engineer::text,true);
 execute 'set local role authenticated';
 oid:=public.award_quote(q2,'Proposta dentro da alçada delegada');
 execute 'reset role';
 if not exists(select 1 from public.purchase_orders where id=oid and approved_by=engineer and approval_status='APPROVED') then raise exception 'Delegated quote award failed';end if;
 perform set_config('request.jwt.claim.sub',master_id::text,true);
 -- A new project without a baseline must force its orders to the Master.
 insert into public.projects(company_id,name,code,created_by) values(cid,'Access without baseline','ACCESS-'||left(gen_random_uuid()::text,8),master_id) returning id into pid2;
 perform public.save_project_access(pid2,engineer,true,'{"maxAmount":1000,"maxDeviation":100}');
 oid:=(public.procurement_action('ORDER',pid2,jsonb_build_object('supplier','ACCESS missing base','items',jsonb_build_array(jsonb_build_object('code',cat.catalog_code,'source','shared','unit',cat.unit,'quantity',1,'unitPrice',1))))->>'id')::uuid;
 perform set_config('request.jwt.claim.sub',engineer::text,true);
 if (public.evaluate_order_approval(oid)->>'allowed')::boolean then raise exception 'Missing baseline bypass';end if;
 perform set_config('request.jwt.claim.sub',master_id::text,true);
 perform public.decide_purchase_order(pid2,oid,true,'Exceção autorizada pelo gestor');
 insert into public.projects(company_id,name,code,created_by) values(cid,'Access new project','ACCESS-'||left(gen_random_uuid()::text,8),master_id) returning id into pid2;
 perform set_config('request.jwt.claim.sub',engineer::text,true);
 if public.can_access_project(pid2) then raise exception 'New project automatically granted';end if;
 begin perform public.procurement_action('STOCK',pid,jsonb_build_object('destinationProjectId',pid2,'direction','OUT'));raise exception 'ASSERT transfer bypass';exception when others then if sqlerrm='ASSERT transfer bypass' or position('acesso a esta obra' in sqlerrm)=0 then raise;end if;end;
end $$;
rollback;
